<?php
use App\Http\Controllers\Admin\{AdminDashboardController,AdminUserController,AdminContentController,AdminNotificationController,AdminReportController,AdminAccountController,AdminLogController};
use App\Http\Controllers\Admin\Auth\AdminLoginController;
use Illuminate\Support\Facades\Route;
Route::post('/admin/hidden-login',[AdminLoginController::class,'login'])->middleware('throttle:5,1')->name('admin.hidden.login');
Route::prefix('admin')->name('admin.')->middleware(['auth','admin','admin.idle'])->group(function(){Route::get('/',[AdminDashboardController::class,'index'])->name('dashboard');Route::post('/logout',[AdminLoginController::class,'logout'])->name('logout');Route::get('/users',[AdminUserController::class,'index'])->name('users.index');Route::patch('/users/{user}/toggle',[AdminUserController::class,'toggle'])->name('users.toggle');Route::get('/content/{type}',[AdminContentController::class,'index'])->name('content.index');Route::patch('/content/{type}/{id}/status',[AdminContentController::class,'status'])->name('content.status');Route::delete('/content/{type}/{id}',[AdminContentController::class,'destroy'])->name('content.destroy');Route::get('/notifications',[AdminNotificationController::class,'index'])->name('notifications.index');Route::post('/notifications',[AdminNotificationController::class,'store'])->name('notifications.store');Route::get('/reports',[AdminReportController::class,'index'])->name('reports.index');Route::get('/reports.csv',[AdminReportController::class,'csv'])->name('reports.csv');Route::get('/logs',[AdminLogController::class,'index'])->name('logs.index');Route::get('/account',[AdminAccountController::class,'edit'])->name('account.edit');Route::put('/account',[AdminAccountController::class,'update'])->name('account.update');});
